function renderMirrors(){$('#mirror-tools').hidden=mode==='export';$('#explode').hidden=mode!=='paint';$('#explode').classList.toggle('active',exploded);$('#explode').setAttribute('aria-pressed',String(exploded));const animate=mode==='animate';$('#mirror-tools').classList.toggle('animate-controls',animate);$('#joints').hidden=!(animate||mode==='build');$('#add-animation').hidden=!animate;$('#joints').innerHTML=icon('joint');$('#joints').classList.toggle('active',showJoints);$('#joints').setAttribute('aria-pressed',String(showJoints));$('#add-animation').innerHTML=icon('add')+'<span>Anim</span>';for(const button of $('#mirror-tools').querySelectorAll('[data-mirror]')){const enabled=mirrors[button.dataset.mirror];button.classList.toggle('active',enabled);button.setAttribute('aria-pressed',String(enabled));button.disabled=false;}$('#mirror-tools').setAttribute('aria-label',mode==='build'?'Build mirroring':mode==='paint'?'Paint mirroring':'Mirroring');}
function advancedPaintSheet(){
 clearBrushPreview();showSheet(`<div class="sheet-row"><span class="sheet-label">Advanced</span><button class="icon-button close-sheet" aria-label="Close">${icon('close')}</button></div>${[['opacity','Opacity',brushOpacity],['emission','Emission',brushEmission],['metalness','Metalness',brushMetalness]].map(([id,label,value])=>`<label class="material-setting"><span>${label}</span><input id="brush-${id}" aria-label="Brush ${id}" type="range" min="0" max="100" value="${Math.round(value*100)}"><output for="brush-${id}">${Math.round(value*100)}%</output></label>`).join('')}`,'paint-advanced');
 for(const name of ['opacity','emission','metalness'])$('#brush-'+name).oninput=e=>{const value=+e.target.value/100;if(name==='opacity')brushOpacity=value;else if(name==='emission')brushEmission=value;else brushMetalness=value;e.target.nextElementSibling.value=Math.round(value*100)+'%';clearBrushPreview();autosave.schedule();};
}
function paintTimelineHTML(){return `<div class="paint-layer-row" aria-label="Paint layer frames"><button id="paint-base" class="tool ${paintTarget==='base'?'active':''}" aria-label="Paint base texture" aria-pressed="${paintTarget==='base'}">Base</button><div id="paint-frames" class="frames">${paintLayer().frames.map((f,i)=>`<button class="frame ${paintTarget==='layer'&&paintLayer().frame===i?'active':''}" data-paint-frame="${i}" aria-label="Texture layer frame ${i+1}" aria-pressed="${paintTarget==='layer'&&paintLayer().frame===i}">${icon('key')}<span>${i+1}</span></button>`).join('')}</div><button id="add-paint-frame" class="icon-button" aria-label="Add texture layer frame">${icon('add')}</button></div>`;}
function choosePaintFrame(index){input.reset();atlasView.reset();commit();closeSheet();paintTarget=index===null?'base':'layer';if(index!==null)paintLayer().frame=index;refreshPaint();renderTools();}
function bindPaintTimeline(){
 $('#paint-base').onclick=()=>choosePaintFrame(null);
 for(const button of document.querySelectorAll('[data-paint-frame]'))button.onclick=()=>{const index=+button.dataset.paintFrame,same=paintTarget==='layer'&&paintLayer().frame===index;if(same&&$('#sheet')?.dataset.kind==='paint-keyframe'){closeSheet();return;}choosePaintFrame(index);if(same)paintFrameSheet();};
 $('#add-paint-frame').onclick=()=>{input.reset();atlasView.reset();commit();if(paintLayer().frames.length>=16)return notify('16 texture frames maximum');begin();appendPaintFrame(paintLayer());paintTarget='layer';refreshPaint();commit();renderTools();$('#paint-frames').scrollLeft=99999;};
}
function paintFrameSheet(){showSheet(`<div class="sheet-row"><span class="sheet-label">Texture frame ${paintLayer().frame+1}</span><button class="icon-button close-sheet" aria-label="Close">${icon('close')}</button></div><div class="frame-actions"><button id="copy-paint-frame" class="sheet-action">${icon('copy')}<span>Copy</span></button><button id="paste-paint-frame" class="sheet-action" ${paintClipboard?'':'disabled'}>${icon('paste')}<span>Paste</span></button></div><button id="clear-paint-frame" class="sheet-action">${icon('erase')}<span>Clear</span></button><button id="delete-paint-frame" class="sheet-action" ${paintLayer().frames.length<2?'disabled':''}>${icon('trash')}<span>Delete</span></button>`,'paint-keyframe');
 $('#copy-paint-frame').onclick=()=>{paintClipboard={...paintLayer().frames[paintLayer().frame],layout:clone(activeLayout)};closeSheet();notify('Texture frame copied');};
 $('#paste-paint-frame').onclick=async()=>{if(!paintClipboard)return;const app=$('#app');app.inert=true;try{await layerSurface.prepare({frames:[paintClipboard]});for(const m of Object.values(materialMaps.maps))await m.surface.prepare({frames:[paintClipboard]});begin();for(const [name,m] of Object.entries(materialMaps.maps)){paintLayer().frames[paintLayer().frame][name]=m.surface.remap(paintClipboard[name],state.boxes,activeLayout,paintClipboard.layout);m.surface.active=null;}paintLayer().frames[paintLayer().frame].png=layerSurface.remap(paintClipboard.png,state.boxes,activeLayout,paintClipboard.layout);layerSurface.active=null;refreshPaint();commit();closeSheet();notify('Texture frame pasted');}catch{notify('Unable to paste texture frame');}finally{app.inert=false;}};
 $('#clear-paint-frame').onclick=()=>{begin();paintLayer().frames[paintLayer().frame]={png:''};layerSurface.active=null;refreshPaint();commit();closeSheet();};
 $('#delete-paint-frame').onclick=()=>{begin();deletePaintFrame(paintLayer(),state.animations);refreshPaint();commit();closeSheet();renderTools();};
}

function selectAnimation(index){stopPlayback();endDrag();closeSheet();state.animation=index;state.frame=0;if(!frames().length)frames().push({time:0,pose:restPose(),paintFrame:-1});displayPose(frames()[0].pose);refreshPaint();makePhysics();renderTools();}
function addAnimation(){closeSheet();if(state.animations.length>=16)return notify('16 animations maximum');stopPlayback();endDrag();begin();const id=state.nextAnimationId++;state.animations.push({id,name:`Animation ${id+1}`,frames:[{time:0,pose:restPose(),paintFrame:-1}]});state.animation=state.animations.length-1;state.frame=0;displayPose(frames()[0].pose);makePhysics();commit();renderTools();$('.animation-rows').scrollTop=99999;}
function resetPose(){stopPlayback();endDrag();begin();frames()[state.frame].pose=restPose();displayPose(frames()[state.frame].pose);makePhysics();commit();renderTools();}
function selectFrame(i){stopPlayback();endDrag();state.frame=i;displayPose(frames()[i].pose);refreshPaint();makePhysics();renderTools();}
function addFrame(){closeSheet();stopPlayback();endDrag();if(frames().length>=60)return notify('60 keyframes maximum');const time=frames().at(-1).time+.5;if(time>60)return notify('60 seconds maximum');begin();frames().push({time,pose:currentPose(),paintFrame:frames()[state.frame]?.paintFrame??0});state.frame=frames().length-1;commit();renderTools();$(`[data-animation="${state.animation}"] .frames`)?.scrollTo({left:99999,behavior:'smooth'});}
function deleteFrame(){if(frames().length<2)return;stopPlayback();begin();frames().splice(state.frame,1);state.frame=Math.max(0,state.frame-1);frames()[0].time=0;displayPose(frames()[state.frame].pose);makePhysics();commit();renderTools();}
function togglePlayback(){if(playing){stopPlayback();return;}if(frames().length<2)return notify('Add another keyframe to play');endDrag();closeSheet();playing=true;playStart=performance.now();ghost.visible=false;renderTools();}
function stopPlayback(){if(!playing)return;playing=false;refreshPaint();if(mode==='animate'&&frames()[state.frame])displayPose(frames()[state.frame].pose);makePhysics();renderTools();}
function interpolatePose(a,b,t){const out={};for(const box of state.boxes){const ap=a[box.id]||box,bp=b[box.id]||box;if(box.parent===null){out[box.id]={p:vec(ap.p).lerp(vec(bp.p),t).toArray(),q:quat(ap.q).slerp(quat(bp.q),t).toArray()};}else{const pa=a[box.parent],pb=b[box.parent],parent=out[box.parent],lqa=quat(pa.q).invert().multiply(quat(ap.q)),lqb=quat(pb.q).invert().multiply(quat(bp.q));const parentBox=state.boxes.find(b=>b.id===box.parent);const q=quat(parent.q).multiply(constrainedRelative(box,parentBox,lqa.slerp(lqb,t)));const p=vec(box.a).applyQuaternion(quat(parent.q)).add(vec(parent.p)).sub(vec(box.b).applyQuaternion(q));out[box.id]={p:p.toArray(),q:q.toArray()};}}return out;}
function playTick(now){const end=frames().at(-1).time;if(end<=0)return;const elapsed=(now-playStart)/1000;if(state.animations[state.animation].loop===false&&elapsed>=end){state.frame=frames().length-1;stopPlayback();return;}const t=elapsed%end;let i=0;while(i<frames().length-2&&frames()[i+1].time<=t)i++;const a=frames()[i],b=frames()[i+1],paintIndex=paintFrameForPose(a,paintLayer());if(layerSurface.lastPreview!==paintIndex)refreshPaint(paintIndex);displayPose(interpolatePose(a.pose,b.pose,(t-a.time)/(b.time-a.time)));}
function jointSheet(id){selected=id;axisGuideJoint=id;updateSelection();const b=state.boxes.find(b=>b.id===id);showSheet(`<div class="sheet-row"><span class="sheet-label">Rotation axis</span><button class="icon-button close-sheet" aria-label="Close">${icon('close')}</button></div><div class="axis-options">${['omni','x','y','z'].map(a=>`<button data-axis="${a}" class="axis-button ${b.axis===a?'active':''}" aria-label="Joint axis ${a==='omni'?'Omni':a.toUpperCase()}" aria-pressed="${b.axis===a}">${a==='omni'?'Omni':a.toUpperCase()}</button>`).join('')}</div>`);updateAxisGuide();for(const button of $('#sheet').querySelectorAll('[data-axis]'))button.onclick=()=>{stopPlayback();begin();b.axis=button.dataset.axis;for(const f of allFrames(state))f.pose=projectPose(state.boxes,f.pose);if(mode==='animate')displayPose(frames()[state.frame].pose);makePhysics();updateJoints();commit();for(const option of $('#sheet').querySelectorAll('[data-axis]')){option.classList.toggle('active',option.dataset.axis===b.axis);option.setAttribute('aria-pressed',String(option.dataset.axis===b.axis));}};}
function keyframeSheet(){showSheet(`<div class="sheet-row"><label class="time-label">Time <input id="frame-time" aria-label="Keyframe time in seconds" type="number" min="0" max="60" step="0.05" value="${frames()[state.frame].time}" ${state.frame===0?'disabled':''}> s</label><button class="icon-button close-sheet" aria-label="Close">${icon('close')}</button></div><div class="frame-actions"><button id="copy-frame" class="sheet-action">${icon('copy')}<span>Copy</span></button><button id="paste-frame" class="sheet-action" ${frameClipboard?'':'disabled'}>${icon('paste')}<span>Paste</span></button></div><label class="texture-frame-choice"><span>Texture frame</span><select id="pose-paint-frame" aria-label="Animation texture frame"><option value="-1" ${paintFrameForPose(frames()[state.frame],paintLayer())===-1?'selected':''}>Base</option>${paintLayer().frames.map((f,i)=>`<option value="${i}" ${i===paintFrameForPose(frames()[state.frame],paintLayer())?'selected':''}>${i+1}</option>`).join('')}</select></label><label class="texture-frame-choice"><span>Animation loop</span><input id="animation-loop" type="checkbox" ${state.animations[state.animation].loop!==false?'checked':''}></label><label class="texture-frame-choice"><span>Animation priority</span><select id="animation-priority" aria-label="Animation priority">${['Core','Idle','Movement','Action','Action2','Action3','Action4'].map(p=>`<option ${p===(state.animations[state.animation].priority||'Action')?'selected':''}>${p}</option>`).join('')}</select></label><button id="reset-pose" class="sheet-action">${icon('reset')}<span>Reset pose</span></button><button id="delete-frame" class="sheet-action" ${frames().length<2?'disabled':''}>${icon('trash')}<span>Delete keyframe</span></button>`,'keyframe');$('#animation-loop').onchange=e=>{begin();state.animations[state.animation].loop=e.target.checked;commit();};$('#animation-priority').onchange=e=>{begin();state.animations[state.animation].priority=e.target.value;commit();};$('#pose-paint-frame').onchange=e=>{begin();frames()[state.frame].paintFrame=+e.target.value;refreshPaint();commit();};$('#reset-pose').onclick=()=>{resetPose();closeSheet();};$('#frame-time').onchange=e=>{const t=+e.target.value;if(!Number.isFinite(t)||t<=0||t>60||frames().some((f,i)=>i!==state.frame&&Math.abs(f.time-t)<.001)){keyframeSheet();return;}begin();const f=frames()[state.frame];f.time=t;frames().sort((a,b)=>a.time-b.time);state.frame=frames().indexOf(f);commit();renderTools();keyframeSheet();};$('#delete-frame').onclick=()=>{deleteFrame();closeSheet();};$('#copy-frame').onclick=()=>{frameClipboard={pose:clone(frames()[state.frame].pose),paintFrame:frames()[state.frame].paintFrame??0};closeSheet();notify('Keyframe copied');};$('#paste-frame').onclick=()=>{if(!frameClipboard)return;begin();const f=frames()[state.frame];f.pose=pastePose(state.boxes,f.pose,frameClipboard.pose);f.paintFrame=Math.min(frameClipboard.paintFrame,paintLayer().frames.length-1);refreshPaint();displayPose(f.pose);makePhysics();commit();closeSheet();notify('Keyframe pasted');};}

function anchorSheet(id){selected=id;updateSelection();const b=state.boxes.find(b=>b.id===id);showSheet(`<div class="sheet-row"><button id="anchor-action" class="sheet-action">${icon(b.anchor?'unlock':'anchor')}<span>${b.anchor?'Unanchor':'Anchor'} cube</span></button><button class="icon-button close-sheet" aria-label="Close">${icon('close')}</button></div>`);$('#anchor-action').onclick=()=>{begin();b.anchor=!b.anchor;for(const p of mirrorPartners(state.boxes,b.id,mirrors))state.boxes.find(b=>b.id===p.id).anchor=b.anchor;makePhysics();updateJoints();commit();closeSheet();};}
function showSheet(html,kind=''){closeSheet();const el=document.createElement('section');el.id='sheet';el.dataset.kind=kind;el.setAttribute('aria-label','Actions');el.innerHTML=html;el.style.bottom=(innerHeight-$('#dock').getBoundingClientRect().top+12)+'px';el.style.maxHeight=Math.max(80,$('#dock').getBoundingClientRect().top-$('.modes').getBoundingClientRect().bottom-24)+'px';$('#app').appendChild(el);el.querySelectorAll('.close-sheet').forEach(b=>b.onclick=closeSheet);el.querySelector('button')?.focus();}
function closeSheet(){$('#sheet')?.remove();}
async function importTexture(file){const app=$('#app');app.inert=true;let url;try{if(file.size>16*1024*1024)throw Error('Choose a PNG under 16 MB');const header=new Uint8Array(await file.slice(0,24).arrayBuffer());if(header.length<24||![137,80,78,71,13,10,26,10].every((v,i)=>header[i]===v))throw Error('Choose a PNG texture');const view=new DataView(header.buffer),width=view.getUint32(16),height=view.getUint32(20);if(width!==height||width<1||width>4096)throw Error('Choose a square PNG up to 4096 × 4096');url=URL.createObjectURL(file);const image=new Image();await new Promise((resolve,reject)=>{image.onload=resolve;image.onerror=()=>reject(Error('Unable to read this PNG'));image.src=url;});input.reset();atlasView.reset();begin();if(paintTarget==='layer')layerSurface.touch();else touchAtlas();const ctx=paintContext();ctx.imageSmoothingEnabled=false;ctx.clearRect(0,0,SIZE,SIZE);ctx.drawImage(image,0,0,SIZE,SIZE);texture.needsUpdate=true;commit();closeSheet();renderTools();notify('Texture imported');}catch(error){notify(error.message||'Unable to import texture');}finally{if(url)URL.revokeObjectURL(url);app.inert=false;}}
function textureSheet(){showSheet(`<div class="sheet-row"><span class="sheet-label">${paintTarget==='layer'?'Layer frame':'Base texture'}</span><button class="icon-button close-sheet" aria-label="Close">${icon('close')}</button></div><button id="export-texture" class="sheet-action">${icon('download')}<span>Export PNG</span></button><button id="import-texture" class="sheet-action">${icon('folder')}<span>Import PNG<small>Shared atlas · fits to ${SIZE} × ${SIZE}</small></span></button><input id="texture-file" type="file" accept="image/png,.png" hidden>`,'texture');$('#export-texture').onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{const png=await new Promise((resolve,reject)=>paintCanvas().toBlob(blob=>blob?resolve(blob):reject(Error('Unable to export texture')),'image/png'));triggerDownload(png,'cube-texture.png','image/png');closeSheet();}catch(error){notify(error.message);button.disabled=false;}};$('#import-texture').onclick=()=>$('#texture-file').click();$('#texture-file').onchange=e=>{const file=e.target.files[0];e.target.value='';if(file)importTexture(file);};}
function newProject(){paintClipboard=null;paintTarget='base';input.reset();atlasView.reset();stopPlayback();endDrag();commit();begin();touchAtlas();state=freshProject();frameClipboard=null;selected=null;axisGuideJoint=null;mode='build';tool='move';cameraMode=false;textureView=false;exploded=false;mirrors={x:false,y:false,z:false};const layout=packPixelAtlas(state.boxes,state.pixelDensity);state.textureSize=layout.size;state.atlasLayout=layout;setAtlasSize(layout.size,null,layout);repackPixels(ctx,atlas,state.boxes,layout,null,null);texture.needsUpdate=true;rebuild();commit();closeSheet();renderTools();fit();notify('New project · Undo to restore');}
async function openProjectFile(file){const app=$('#app');app.inert=true;try{const loaded=await readProject(file);input.reset();atlasView.reset();stopPlayback();endDrag();commit();begin();touchAtlas();state=migratePixelSettings(loaded.state);await layerSurface.prepare(paintLayer(),loaded.layerImages);await materialMaps.prepare();paintClipboard=null;frameClipboard=null;axisGuideJoint=null;selected=null;exploded=false;loadAtlas(loaded);if(loaded.editor)restoreEditor(loaded.editor);rebuild();commit();closeSheet();renderTools();fit();notify('Project opened');}catch(err){notify(err instanceof SyntaxError?'Choose a Cube Studio ZIP or an older .cube project':err.message||'Unable to open project');}finally{app.inert=false;}}
function renderExportPanel(panel){
 panel.innerHTML=`<label class="export-name"><span>Name</span><input id="export-name" aria-label="Asset name" type="text" maxlength="80" placeholder="cube-asset" autocomplete="off" spellcheck="false"></label><label class="export-option"><input id="fuse-static-joints" type="checkbox" ${fuseStaticJoints?'checked':''}><span>Fuse static joints</span></label><button id="download-model" class="sheet-action primary">${icon('download')}<span>Download</span></button><button id="new-project" class="sheet-action">${icon('add')}<span>New project</span></button><label id="open-project" class="sheet-action file-action">${icon('folder')}<span>Open project</span><input type="file" id="project-file" aria-label="Open project"></label>`;
 const nameInput=$('#export-name');nameInput.value=state.name||'';
 $('#fuse-static-joints').onchange=e=>{fuseStaticJoints=e.target.checked;autosave.schedule();};
 const saveName=()=>{const name=nameInput.value.trim();if(name!==state.name){begin();state.name=name;commit();}};
 nameInput.onchange=saveName;$('#new-project').onclick=newProject;
 $('#project-file').onchange=e=>{const file=e.target.files[0];e.target.value='';if(file)openProjectFile(file);};
 $('#download-model').onclick=async()=>{const btn=$('#download-model');btn.disabled=true;try{saveName();commit();layerSurface.flush();refreshPaint();await downloadBundle(state,atlas,meshes,editorSettings(),layerSurface.composite);notify('Project ZIP exported');}catch(error){notify(error.message||'Export failed. Try again.');}finally{btn.disabled=false;}};
}

let gesture=null;
function perspectiveView(){if(camera.isOrthographicCamera){camera=new THREE.PerspectiveCamera(36,innerWidth/innerHeight,.05,150);viewPlane=null;updateWorkArea();}camera.up.set(0,1,0);}
function orbitCamera(dx,dy){perspectiveView();theta-=dx*.008;phi=clamp(phi-dy*.008,.001,Math.PI-.001);updateCamera();}
function planeView(name){input.reset();atlasView.reset();closeSheet();const directions={front:[0,0,1],back:[0,0,-1],right:[1,0,0],left:[-1,0,0],top:[0,1,0],bottom:[0,-1,0]},d=vec(directions[name]);camera=new THREE.OrthographicCamera(-1,1,1,-1,.05,150);camera.aspect=innerWidth/innerHeight;camera.up.set(0,1,0);if(name==='top')camera.up.set(0,0,-1);if(name==='bottom')camera.up.set(0,0,1);theta=Math.atan2(d.x,d.z);phi=Math.acos(d.y);viewPlane=name;textureView=false;renderTools();updateCamera();}
function cameraPan(dx,dy){const scale=radius*.0015;const right=new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld,0),up=new THREE.Vector3().setFromMatrixColumn(camera.matrixWorld,1);target.addScaledVector(right,-dx*scale).addScaledVector(up,dy*scale);updateCamera();}
canvas.addEventListener('contextmenu',e=>e.preventDefault());
const input=bindPointerInput(canvas,{
 begin(e){clearBrushPreview();const p={x:e.clientX,y:e.clientY};closeSheet();let h=hit(p.x,p.y);if(playing&&mode==='animate'&&h){stopPlayback();h=hit(p.x,p.y);}const joint=!cameraMode&&!playing?pickJoint(p.x,p.y):null,handle=mode==='build'&&tool==='move'&&!cameraMode?pickCorner(p.x,p.y):null,corner=handle&&(!joint||handle.distance<joint.distance)?handle:null;const kind=mode==='export'||cameraMode||(e.pointerType!=='touch'&&e.button!==0)||playing?'camera':corner?'resize':joint?'joint':!h?'camera':mode==='paint'?'paint':mode==='animate'?'pose':tool==='move'?'move':'build';if(kind==='move'){selected=h.object.userData.id;updateSelection();updateJoints();}if(kind!=='joint'){axisGuideJoint=null;updateAxisGuide();}const fillKeyValue=kind==='paint'&&tool==='fill'?fillKey(h):null,previousFill=fillTaps.take(fillKeyValue,p.x,p.y,performance.now());gesture={fillKey:fillKeyValue,doubleFill:!!previousFill,painted:previousFill?new Set(previousFill.painted):new Set(),start:p,last:p,hit:h,corner,joint,moved:false,kind,emptySelect:!h&&!corner&&!joint&&mode==='build'&&tool==='move'&&!cameraMode,pan:e.shiftKey||(e.pointerType!=='touch'&&e.button===2)};ghost.visible=false;if(kind==='paint'){if(tool!=='picker')begin();if(!gesture.doubleFill)paintAt(p.x,p.y);}},
 move(e){if(!gesture)return;const p={x:e.clientX,y:e.clientY},g=gesture,dx=p.x-g.last.x,dy=p.y-g.last.y;if(Math.hypot(p.x-g.start.x,p.y-g.start.y)>5)g.moved=true;if(g.kind==='joint'&&g.moved&&mode==='build'){selected=g.joint.id;g.kind='jointMove';updateSelection();}if(g.kind==='joint'&&g.moved&&mode==='animate'){const m=meshes.get(g.joint.id);g.hit={object:m,point:g.hit?.object===m?g.hit.point:m.position.clone()};g.kind='pose';}if(g.kind==='camera'){if(g.pan)cameraPan(dx,dy);else{orbitCamera(dx,dy);}}else if(g.kind==='paint')stroke(g.last,p);else if((g.kind==='move'||g.kind==='resize'||g.kind==='jointMove')&&g.moved)moveShape(g,p.x,p.y);else if(g.kind==='pose'&&g.moved){if(!g.dragStarted){g.dragStarted=startDrag(g.hit);if(!g.dragStarted)g.kind='blocked';}if(g.dragStarted)moveDrag(p.x,p.y);}else if(g.kind==='build'&&g.moved){g.kind='camera';orbitCamera(dx,dy);}g.last=p;},
 end(cancel){const g=gesture;gesture=null;if(!g)return;if(g.kind==='paint'){if(g.fillKey&&!cancel&&!g.moved){if(g.doubleFill)fillCube(g.hit,g.painted);else fillTaps.remember(g.fillKey,g.start.x,g.start.y,performance.now(),g.painted);}else fillTaps.reset();commit();}if(g.base)endShape(g);if(g.dragStarted)endDrag();if(!cancel&&!g.moved){if(g.emptySelect){selected=null;axisGuideJoint=null;updateSelection();updateJoints();}if(g.kind==='build'){if(tool==='add')addCube(g.hit);else eraseCube(g.hit.object.userData.id);}if(g.kind==='pose')anchorSheet(g.hit.object.userData.id);if(g.kind==='joint')jointSheet(g.joint.id);}if(cancel){endDrag();commit();}},
 multi(previous,next){radius=clamp(radius*previous.d/next.d,1.8,80);cameraPan(next.x-previous.x,next.y-previous.y);},
 hover(e){if(e.pointerType!=='touch'&&mode==='paint'&&!cameraMode){previewBrush(()=>paintAt(e.clientX,e.clientY));return;}clearBrushPreview();if(mode==='build'&&tool==='add'&&!cameraMode&&e.pointerType!=='touch'){const h=hit(e.clientX,e.clientY);if(h){const c=candidate(h);ghost.visible=!state.boxes.some(b=>vec(b.p).distanceTo(c)<.1);ghost.position.copy(c);ghost.quaternion.copy(h.object.quaternion);ghost.scale.set(1,1,1);}else ghost.visible=false;}}
});
canvas.addEventListener('pointerleave',()=>{ghost.visible=false;clearBrushPreview();});
addEventListener('blur',clearBrushPreview);
document.addEventListener('pointerdown',e=>{if(e.target!==canvas){clearBrushPreview();fillTaps.reset();}},true);

