document.addEventListener('selectstart',e=>e.preventDefault());document.addEventListener('dragstart',e=>e.preventDefault());document.addEventListener('dblclick',e=>e.preventDefault(),{passive:false});
addEventListener('keydown',e=>{if($('#app').inert)return;if(e.target.matches('input,textarea,select')||e.target.isContentEditable)return;if(mode==='paint'&&!gesture&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&!e.repeat){const next={b:'brush',f:'fill',i:'picker',e:'paint-erase'}[e.key.toLowerCase()];if(next){e.preventDefault();tool=next;cameraMode=false;renderTools();autosave.schedule();return;}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();historyStep(e.shiftKey);}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='y'){e.preventDefault();historyStep(true);}if(e.key==='Escape'){input.reset();axisGuideJoint=null;closeSheet();stopPlayback();cameraMode=false;renderTools();}if(e.code==='Space'&&mode==='animate'){e.preventDefault();togglePlayback();}});
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);updateWorkArea();updateCamera();atlasView?.resize();});

viewCube=createViewCube($('#app'),{select:planeView,orbit:orbitCamera,recenter:()=>{if(atlasView.visible)atlasView.fit();else fit(false);}});
atlasView=createTextureView({root:$('#app'),atlas:layerSurface.composite,rects:()=>Object.values(activeLayout.faces),begin:()=>{clearBrushPreview();begin();},paint:paintAtlasAt,end:commit,hover:(x,y)=>previewBrush(()=>paintAtlasAt(x,y)),leave:clearBrushPreview,canPan:()=>false});
addEventListener('pagehide',()=>{atlasView.reset();input.reset();autosave.flush();});document.addEventListener('visibilitychange',()=>{if(document.hidden){atlasView.reset();input.reset();autosave.flush();}});
const restored=await restoreAutosave();rebuild();renderTools();if(restored)fit();else updateCamera();autosave.ready=true;let last=performance.now();renderer.setAnimationLoop(now=>{const dt=Math.min((now-last)/1000,.05);last=now;if(playing)playTick(now);else if(mode==='animate'&&dragConstraint){easeDrag(dt);const pose=mirrorAnimationPose(state.boxes,stepRigPhysics(state.boxes,world,bodies,dt),poseMirrorPairs);for(const pair of poseMirrorPairs){const b=bodies.get(pair.target),p=pose[pair.target];b.position.set(...p.p);b.quaternion.set(...p.q);b.velocity.setZero();b.angularVelocity.setZero();b.aabbNeedsUpdate=true;}displayPose(pose);}renderer.render(scene,camera);atlasView.render();});
